    <div className="report-filters"><label>Jenis konversi<Select aria-label="Jenis konversi laporan" value={conversionMode} onChange={e=>setConversionMode(e.target.value)}><option value="realtime">Real-Time · status terkini</option><option value="events">Event · waktu kejadian</option></Select></label><div className="period-presets" role="group" aria-label="Periode laporan">{[[1,"Hari ini"],[7,"7 hari"],[30,"30 hari"]].map(([days,label])=><button type="button" key={days} onClick={()=>applyPreset(Number(days))}>{label}</button>)}</div><label>Dari<Input aria-label="Tanggal mulai" type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)}/></label><span>sampai</span><label>Sampai<Input aria-label="Tanggal akhir" type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label><Button variant="secondary" size="sm" onClick={()=>void reload()} disabled={busy}>Terapkan</Button><span className="report-period">MATA UANG WORKSPACE · IDR</span></div>
