    <div className="report-summary report-summary-five"><div><span>Ad spend</span><b>{money(totalSpend)}</b></div><div><span>Lead WhatsApp</span><b>{totals.whatsapp}</b></div><div><span>Closing</span><b>{totals.closing}</b></div><div><span>Revenue closing</span><b>{money(totals.revenue)}</b></div><div><span>ROAS iklan</span><b>{roas===null?"—":`${roas.toFixed(2)}×`}</b></div></div>
