  const saveSwipe=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const values=Object.fromEntries(new FormData(e.currentTarget));try{await api(editingAd?`/api/ad-research/swipe/${editingAd.id}`:"/api/ad-research/swipe",{method:editingAd?"PATCH":"POST",body:JSON.stringify(values)});setSwipeOpen(false);setEditingAd(null);notify(editingAd?"Iklan diperbarui.":"Iklan disimpan ke swipe file.");await reload()}catch(error){notify(error instanceof Error?error.message:"Iklan belum tersimpan.")}finally{setBusy(false)}};
