    {competitorOpen&&<Dialog title="Tambah kompetitor" onClose={()=>setCompetitorOpen(false)}><form className="dialog-form" onSubmit={saveCompetitor}><p className="dialog-intro">ID Page ada di halaman Transparansi Page di Facebook, atau di alamat Ad Library (view_all_page_id).</p><label>Nama<Input name="name" required maxLength={100} placeholder="Nama brand atau bisnis"/></label><label>ID atau link Page Facebook<Input name="page_ref" maxLength={300} placeholder="ID Page atau facebook.com/nama-page"/><small>Tanpa ID, Ad Library dibuka menggunakan kata kunci.</small></label><label>Kata kunci (opsional)<Input name="search_terms" maxLength={160} placeholder="Produk, penawaran, atau kategori"/></label><label>Negara di Ad Library<Select name="country" defaultValue="ID">{adCountries.map(([code,name])=><option key={code} value={code}>{name}</option>)}</Select></label><label>Catatan (opsional)<textarea name="note" maxLength={500} rows={3} placeholder="Catatan untuk tim"/></label><div className="dialog-actions"><Button type="button" variant="secondary" onClick={()=>setCompetitorOpen(false)}>Batal</Button><Button disabled={busy}>{busy?"Menyimpan…":"Simpan kompetitor"}</Button></div></form></Dialog>}
