  return <Card className="location-map-panel"><div className="location-map-heading"><div><h2>Sebaran kunjungan</h2><p>Titik menunjukkan pusat perkiraan wilayah, bukan lokasi presisi.</p></div><span><i/> Visit LP</span></div><div className="location-map-scroll"><svg className="indonesia-map" viewBox="0 0 1000 440" role="img" aria-label="Peta sebaran kunjungan leads di Indonesia"><g className="map-land"><path d="M132 72 153 78 168 93 174 111 190 126 185 144 205 156 206 174 221 184 212 202 224 218 218 237 233 250 226 267 237 281 232 298 244 311 234 326 219 317 215 297 201 280 197 261 184 243 181 220 169 205 164 185 151 170 149 150 137 134 140 115 127 99Z"/><path d="M260 330 280 324 301 331 322 329 342 335 362 333 383 340 401 338 414 345 399 352 377 350 358 355 337 349 317 353 296 346 277 350 260 342Z"/><path d="M367 157 394 144 429 148 455 165 471 187 466 209 480 226 470 250 450 264 428 258 414 274 391 261 379 242 365 223 357 200 363 179Z"/><path d="M523 192 543 177 560 183 575 171 592 175 607 164 625 172 619 188 604 196 595 211 579 218 568 234 558 253 551 274 559 294 550 307 540 293 539 269 530 250 526 228 516 212Z"/><path d="M578 221 594 218 605 230 601 247 611 260 604 281 596 295 584 291 587 270 578 252Z"/><path d="M630 194 645 189 654 201 647 215 634 213Z"/><path d="M654 244 666 238 679 248 675 264 662 270 651 261Z"/><path d="M727 214 751 202 777 203 794 192 825 198 846 190 871 202 899 198 922 211 914 232 925 245 904 258 885 261 871 278 851 285 831 277 811 285 790 275 771 280 754 264 738 258 729 239Z"/><path d="M411 356 425 350 440 356 433 362 419 363Z"/><path d="M448 362 462 358 473 365 465 371 451 369Z"/><path d="M482 368 499 362 516 368 531 365 545 372 533 378 514 376 498 381 483 376Z"/><path d="M552 379 568 374 581 380 575 386 560 385Z"/><path d="M604 327 613 321 620 328 615 335Z"/><path d="M636 305 643 300 650 306 645 313Z"/></g>{points.map(point=>{const radius=5+Math.min(10,Math.sqrt(point.visits)*1.4);return <g key={point.name} className="map-point"><circle cx={point.x} cy={point.y} r={radius}/><text x={point.x} y={point.y+3}>{point.visits>99?"99+":point.visits}</text><title>{point.name}: {point.visits} visit</title></g>})}</svg></div><div className="location-map-legend"><span><i/> Wilayah tercatat: {points.length}</span><small>Lokasi dari perkiraan IP Cloudflare; IP mentah tidak disimpan.</small></div></Card>
