function LeadLocationsPage({notify}:{notify:(s:string)=>void}){
  const [from,setFrom]=useState(new Date(Date.now()-29*86400000).toISOString().slice(0,10)),[to,setTo]=useState(new Date().toISOString().slice(0,10)),[data,setData]=useState<any>({totals:{},regions:[]}),[busy,setBusy]=useState(false);
  const reload=useCallback(async()=>{setBusy(true);try{setData(await api<any>(`/api/lead-locations?from=${from}&to=${to}`))}catch(e){notify(e instanceof Error?e.message:"Gagal memuat lokasi lead.")}finally{setBusy(false)}},[from,to,notify]);
  useEffect(()=>{void reload()},[reload]);
  const totals=data.totals??{};const exportCsv=()=>{const quote=(v:any)=>String.fromCharCode(34)+String(v??"").replaceAll(String.fromCharCode(34),String.fromCharCode(34).repeat(2))+String.fromCharCode(34);const csv=[["Wilayah","Negara","Visit LP","Klik CTA","Masuk WA","MQL","Prospek","Closing"],...(data.regions??[]).map((r:any)=>[r.region,r.country,r.visits,r.clicks,r.whatsapp,r.mql,r.prospects,r.closing])].map(row=>row.map(quote).join(",")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"}));a.download="arenka-lokasi-leads.csv";a.click();URL.revokeObjectURL(a.href)};
  return <><PageHeading eyebrow="LEADS / LOKASI" title="Lokasi leads" description="Wilayah kunjungan dan interaksi yang tercatat melalui tracking code." actions={<><Button variant="secondary" onClick={exportCsv} disabled={!data.regions?.length}><ArrowDownRight size={15}/> Unduh CSV</Button><Button onClick={()=>void reload()} disabled={busy}>{busy?"Memuat…":"Perbarui data"}</Button></>}/><div className="report-filters"><label>Dari<Input aria-label="Tanggal mulai lokasi" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><span>sampai</span><label>Sampai<Input aria-label="Tanggal akhir lokasi" type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><Button variant="secondary" size="sm" onClick={()=>void reload()} disabled={busy}>Terapkan</Button><span className="report-period">BERDASARKAN LOKASI IP · TANPA MENYIMPAN IP</span></div><div className="location-metrics">{[["Pengunjung",totals.visitors??0],["Visit LP",totals.visits??0],["Klik CTA",totals.clicks??0],["Masuk WA",totals.whatsapp??0],["MQL",totals.mql??0],["Closing",totals.closing??0]].map(([label,value])=><Card key={String(label)} className="location-metric"><span>{label}</span><b>{Number(value).toLocaleString("id-ID")}</b></Card>)}</div><IndonesiaActivityMap regions={data.regions??[]}/><Card className="table-panel location-panel"><div className="panel-heading report-heading"><div><h2>Distribusi berdasarkan wilayah</h2><p>Wilayah disediakan Cloudflare dari perkiraan lokasi koneksi.</p></div><Badge className="code-status"><MapPin size={12}/> Privasi IP</Badge></div>{data.regions?.length?<div className="table-scroll"><table className="data-table location-table"><thead><tr><th>Wilayah</th><th>Negara</th><th>Visit LP</th><th>Klik CTA</th><th>Masuk WA</th><th>MQL</th><th>Prospek</th><th>Closing</th></tr></thead><tbody>{data.regions.map((r:any)=><tr key={`${r.country}-${r.region}`}><td><b>{r.region}</b></td><td>{r.country||"—"}</td><td>{r.visits||0}</td><td>{r.clicks||0}</td><td>{r.whatsapp||0}</td><td>{r.mql||0}</td><td>{r.prospects||0}</td><td>{r.closing||0}</td></tr>)}</tbody></table></div>:<Empty icon={<MapPin size={19}/>} title="Belum ada data lokasi" text="Lokasi mulai dihitung untuk event baru setelah migrasi database dan tracker terbaru aktif. IP mentah tidak disimpan."/>}</Card></>;
}

